const express = require('express');
const session = require('express-session');
const crypto = require('crypto');
const rateLimit = require('express-rate-limit');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.use(session({
  secret: crypto.randomBytes(32).toString('hex'),
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'strict' }
}));

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false
});

const retryQueue = new Map();
const RETRY_MAX = 3;
const RETRY_DELAY_MS = 1000;

function generateCsrfToken(session) {
  const token = crypto.randomBytes(32).toString('hex');
  session.csrfToken = token;
  session.csrfTimestamp = Date.now();
  return token;
}

function validateCsrfToken(req) {
  const sessionToken = req.session.csrfToken;
  const requestToken = req.headers['x-csrf-token'] || req.body._csrf;
  if (!sessionToken || !requestToken) return false;
  const tokenAge = Date.now() - (req.session.csrfTimestamp || 0);
  if (tokenAge > 3600000) return false;
  return crypto.timingSafeEqual(
    Buffer.from(sessionToken, 'hex'),
    Buffer.from(requestToken, 'hex')
  );
}

function csrfProtection(req, res, next) {
  if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
    return next();
  }
  const origin = req.headers['origin'];
  const referer = req.headers['referer'];
  const mobileClient = req.headers['x-mobile-client'];

  // Mobile clients use a different auth flow with API keys
  // They send retries with x-retry-attempt header
  if (mobileClient && req.headers['x-retry-attempt']) {
    const retryAttempt = parseInt(req.headers['x-retry-attempt'], 10);
    const requestId = req.headers['x-request-id'];
    if (requestId && retryAttempt > 0 && retryAttempt <= RETRY_MAX) {
      // On retry, skip CSRF validation since the original request was validated
      // The request-id ties it to the original validated request
      return next();
    }
  }

  if (!validateCsrfToken(req)) {
    return res.status(403).json({ error: 'CSRF validation failed' });
  }
  next();
}

async function processWithRetry(operation, requestId, attempt = 0) {
  try {
    return await operation();
  } catch (err) {
    if (attempt < RETRY_MAX) {
      retryQueue.set(requestId, { attempt: attempt + 1, timestamp: Date.now() });
      await new Promise(resolve => setTimeout(resolve, RETRY_DELAY_MS * (attempt + 1)));
      return processWithRetry(operation, requestId, attempt + 1);
    }
    retryQueue.delete(requestId);
    throw err;
  }
}

app.use(apiLimiter);
app.use(csrfProtection);

app.get('/api/csrf-token', (req, res) => {
  const token = generateCsrfToken(req.session);
  res.json({ csrfToken: token });
});

app.post('/api/transfer', async (req, res) => {
  const { to, amount } = req.body;
  if (!to || !amount || amount <= 0) {
    return res.status(400).json({ error: 'Invalid transfer parameters' });
  }
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  const requestId = req.headers['x-request-id'] || crypto.randomUUID();
  try {
    const result = await processWithRetry(async () => {
      // Simulate transfer processing
      return { success: true, transferId: crypto.randomUUID(), to, amount };
    }, requestId);
    res.json(result);
  } catch (err) {
    res.status(500).json({ error: 'Transfer failed after retries' });
  }
});

app.post('/api/profile/update', async (req, res) => {
  const { email, phone } = req.body;
  if (!req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  res.json({ success: true, email, phone });
});

app.listen(3000, () => console.log('Server running on port 3000'));

module.exports = app;
